#pragma once
int runVoice401(){juce::ScopedJuceInitialiser_GUI gui;auto require=[](bool ok,const char* label){if(!ok)throw std::runtime_error(label);};try{auto root=LibraryStore::root().getChildFile("Shots");root.createDirectory();auto a=root.getChildFile("Bass C3.wav"),b=root.getChildFile("Bass D3.wav"),loop=LibraryStore::root().getChildFile("Loop.wav");juce::AudioBuffer<float> tone(1,4096);for(int i=0;i<4096;++i)tone.setSample(0,i,.25f*std::sin(i*.043));require(writeRenderedAudio(a,tone,48000)&&writeRenderedAudio(b,tone,48000)&&writeRenderedAudio(loop,tone,48000),"fixtures");LibraryStore::setPlaybackType({root},1);Processor p(false);p.autoSave=false;require(p.load(a),"load");p.shotStart=123;p.shotLoop=true;p.shotLoopStart=1000;p.shotLoopEnd=2000;p.shotOctaveShift=-2;p.shotGainDb=-7;p.shotLegato=true;p.shotEnvelope={.03f,.4f,.5f,.2f};require(p.saveLoop(),"save");auto result=Processor::bulkShotMono({a,b,loop},false);require(result.first==2&&result.second==0,"bulk selected one-shots only");Processor read(false);read.autoSave=false;require(read.load(a)&&!read.shotMono&&read.shotLegato&&read.shotStart==123&&read.shotLoopStart==1000&&read.shotOctaveShift==-2&&read.shotGainDb==-7,"preserve all other saved settings and legato preference");require(read.load(b)&&!read.shotMono,"unsaved one shot default saved");require(LibraryStore::database()->loop(loop.getFullPathName()).isEmpty(),"skip non one-shot");p.shotGainDb=-11;auto xml=p.configurationXml()->toString();result=Processor::bulkShotMono({a,b},true,a.getFullPathName(),xml);require(result.first==2&&read.load(a)&&read.shotMono&&read.shotGainDb==-11,"bulk mono retains unsaved active edits");Editor editor(p);editor.diagnosticQuietAnalysis();require(editor.voice401UiForCheck(),"hide Legato in Poly and restore it in Mono at compact width");std::cout<<"Bulk Mono/Poly, preserved edits, unsaved defaults, skipped loops and Legato visibility passed.\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 4011;}}
